<?php requireRole('student'); ?><section class="hero"><h1>Choose a Course</h1><p>Each course is 25 BHD. Optional one-to-one tutoring is +10 BHD.</p></section><br><div id="courses" class="grid"></div><script>async function load(){let cs=await api('backend/api/course.php?action=list');document.getElementById('courses').innerHTML=cs.map(c=>`<div class="card"><h2>${escapeHTML(c.title)}</h2><p>${escapeHTML(c.description)}</p><div class="price">${c.price_bhd} BHD</div><label><input id="t${c.id}" type="checkbox" style="width:auto"> Add one-to-one tutoring (+10 BHD)</label><br><button class="btn" onclick="enroll(${c.id})">Enroll</button></div>`).join('')}async function enroll(id){let f=new FormData();f.append('action','enroll');f.append('course_id',id);f.append('csrf',window.CSRF);if(document.getElementById('t'+id).checked)f.append('tutoring','1');try{let r=await post('backend/api/course.php',f);alert('Enrollment recorded. Total: '+r.amount+' BHD\nReference: '+r.reference);location.href='index.php?page=lesson&course_id='+id}catch(e){alert(e.message)}}load()</script>
